import{_ as a,o as r,c as i,a2 as o}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"Curriculum Vitae","description":"Academic background, research experience, teaching, honors, and skills of Rubai Mushtaq.","frontmatter":{"title":"Curriculum Vitae","description":"Academic background, research experience, teaching, honors, and skills of Rubai Mushtaq."},"headers":[],"relativePath":"resume.md","filePath":"resume.md"}'),t={name:"resume.md"};function n(s,e,l,h,u,c){return r(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="rubai-mushtaq" tabindex="-1">Rubai Mushtaq <a class="header-anchor" href="#rubai-mushtaq" aria-label="Permalink to &quot;Rubai Mushtaq&quot;">​</a></h1><p><a href="mailto:rubai.mushtaq@gmail.com" target="_blank" rel="noreferrer">rubai.mushtaq@gmail.com</a> • <a href="tel:+918530184722" target="_blank" rel="noreferrer">+91 8530184722</a> • <a href="https://github.com/rubaimushtaq" target="_blank" rel="noreferrer">GitHub</a> • <a href="https://linkedin.com/in/rubai-mushtaq-a7ba5a256" target="_blank" rel="noreferrer">LinkedIn</a></p><hr><h2 id="profile" tabindex="-1">Profile <a class="header-anchor" href="#profile" aria-label="Permalink to &quot;Profile&quot;">​</a></h2><p>Currently in my third year at Ashoka University, I am a Biology major with a minor in Mathematics. During the past year, I have had the opportunity to really dive into evolutionary immunology and the physics of cellular functions, coupled with mathematical modelling. It was during this period of exploration that I developed an interest in dynamical living systems. Whether it&#39;s host-pathogen interactions, infection dynamics, or the perturbations of cellular functions, I hope to study these complex dynamics across all scales.</p><hr><h2 id="education" tabindex="-1">Education <a class="header-anchor" href="#education" aria-label="Permalink to &quot;Education&quot;">​</a></h2><h3 id="ashoka-university" tabindex="-1">Ashoka University <a class="header-anchor" href="#ashoka-university" aria-label="Permalink to &quot;Ashoka University&quot;">​</a></h3><ul><li><strong>Duration</strong>: August 2024 - May 2028</li><li><strong>Major</strong>: Biology | <strong>Minor</strong>: Mathematics</li><li><strong>CGPA</strong>: 3.82 / 4.00 (Major CGPA: 3.90)</li><li><strong>Dean&#39;s List</strong>: Monsoon 2024, Spring 2025, Monsoon 2025, Spring 2026</li></ul><h3 id="drivechange-learning-resource-centre-dlrc" tabindex="-1">DriveChange Learning &amp; Resource Centre (DLRC) <a class="header-anchor" href="#drivechange-learning-resource-centre-dlrc" aria-label="Permalink to &quot;DriveChange Learning &amp; Resource Centre (DLRC)&quot;">​</a></h3><ul><li><strong>Duration</strong>: May 2022 - March 2024</li><li><strong>Board</strong>: Cambridge International AS and A Levels</li><li><strong>A Levels Final Grades</strong>: Mathematics: A*, Physics: A*, Chemistry: A*, Biology: A*</li></ul><h3 id="vidya-valley-school" tabindex="-1">Vidya Valley School <a class="header-anchor" href="#vidya-valley-school" aria-label="Permalink to &quot;Vidya Valley School&quot;">​</a></h3><ul><li><strong>Duration</strong>: June 2012 - May 2022</li><li><strong>Board</strong>: Council for the Indian School Certificate Examinations (ICSE)</li><li><strong>Final Score</strong>: 98.2%</li></ul><hr><h2 id="research-experience" tabindex="-1">Research Experience <a class="header-anchor" href="#research-experience" aria-label="Permalink to &quot;Research Experience&quot;">​</a></h2><h3 id="nius-fellow-iiser-pune" tabindex="-1">NIUS Fellow | IISER Pune <a class="header-anchor" href="#nius-fellow-iiser-pune" aria-label="Permalink to &quot;NIUS Fellow | IISER Pune&quot;">​</a></h3><ul><li><strong>Duration</strong>: June 2025 - August 2025</li><li><strong>Lab</strong>: <a href="https://sites.google.com/view/chromosome-biology-lab/home" target="_blank" rel="noreferrer">Chromosome Biology Lab (CBL)</a></li><li><strong>Mentor</strong>: Dr. Kundan Sengupta, Principal Investigator</li><li><strong>Selection</strong>: Selected out of ~40 participants at the <a href="https://nius.hbcse.tifr.res.in/" target="_blank" rel="noreferrer">National Initiative on Undergraduate Science (NIUS)</a> Biology Camp to pursue mentored research.</li></ul><h3 id="research-intern-ashoka-university" tabindex="-1">Research Intern | Ashoka University <a class="header-anchor" href="#research-intern-ashoka-university" aria-label="Permalink to &quot;Research Intern | Ashoka University&quot;">​</a></h3><ul><li><strong>Duration</strong>: June 2025 - Present</li><li><strong>Lab</strong>: <a href="https://evoecoimmunol.wordpress.com/" target="_blank" rel="noreferrer">Evolutionary Immunology Lab</a></li><li><strong>Mentor</strong>: Dr. Imroze Khan, Principal Investigator</li><li><strong>Focus</strong>: Investigating dual selection pressures of heat stress and bacterial infection on <em>Drosophila melanogaster</em> populations, analyzing evolutionary trajectories of immune responses, signaling pathways, and life history trade-offs.</li></ul><hr><h2 id="teaching-leadership" tabindex="-1">Teaching &amp; Leadership <a class="header-anchor" href="#teaching-leadership" aria-label="Permalink to &quot;Teaching &amp; Leadership&quot;">​</a></h2><h3 id="teaching-assistant-ashoka-university" tabindex="-1">Teaching Assistant | Ashoka University <a class="header-anchor" href="#teaching-assistant-ashoka-university" aria-label="Permalink to &quot;Teaching Assistant | Ashoka University&quot;">​</a></h3><ul><li><strong>Duration</strong>: May 2025 - June 2025</li><li><strong>Program</strong>: <a href="https://www.lodhageniusprogramme.com/" target="_blank" rel="noreferrer">Lodha Genius Program</a></li></ul><h3 id="biology-student-representative-ashoka-university" tabindex="-1">Biology Student Representative | Ashoka University <a class="header-anchor" href="#biology-student-representative-ashoka-university" aria-label="Permalink to &quot;Biology Student Representative | Ashoka University&quot;">​</a></h3><ul><li><strong>Duration</strong>: May 2026 - May 2027</li></ul><h3 id="the-biology-society-at-ashoka-university" tabindex="-1">The Biology Society at Ashoka University <a class="header-anchor" href="#the-biology-society-at-ashoka-university" aria-label="Permalink to &quot;The Biology Society at Ashoka University&quot;">​</a></h3><ul><li><strong>Role</strong>: Head of Events (August 2025 - May 2026)</li></ul><h3 id="student-government-vidya-valley-school" tabindex="-1">Student Government | Vidya Valley School <a class="header-anchor" href="#student-government-vidya-valley-school" aria-label="Permalink to &quot;Student Government | Vidya Valley School&quot;">​</a></h3><ul><li><strong>Role</strong>: Head Girl (June 2021 - May 2022)</li></ul><hr><h2 id="fellowships-camps" tabindex="-1">Fellowships &amp; Camps <a class="header-anchor" href="#fellowships-camps" aria-label="Permalink to &quot;Fellowships &amp; Camps&quot;">​</a></h2><h3 id="nius-biology-camp" tabindex="-1">NIUS Biology Camp <a class="header-anchor" href="#nius-biology-camp" aria-label="Permalink to &quot;NIUS Biology Camp&quot;">​</a></h3><ul><li><strong>Host</strong>: Homi Bhabha Centre for Science Education (TIFR), Mumbai (November 2024)</li><li><strong>Activities</strong>: Rigorous experimental biology training, hypothesis testing, literature synthesis, and oral presentations.</li></ul><hr><h2 id="awards-honors" tabindex="-1">Awards &amp; Honors <a class="header-anchor" href="#awards-honors" aria-label="Permalink to &quot;Awards &amp; Honors&quot;">​</a></h2><ul><li><strong>Wg Cdr Suhas Clement Solomon Award for Extraordinary Achievement</strong>: December 2019, Vidya Valley School</li><li><strong>National Silver Medal, Taekwondo</strong>: August 2019, Gujarat, India</li><li><strong>Black Belt, Taekwondo</strong>: April 2019, Fighters Taekwondo Academy</li></ul>',36)])])}const m=a(t,[["render",n]]);export{g as __pageData,m as default};
